/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import page2020.view.Tag;public class B4list<T> extends B4boxes<T> {	private boolean boxing = false;	public B4list() {		super("ul");	}	public B4list(String tagName) {		super(tagName);	}	public B4list(boolean boxing) {		super("ul");		this.boxing = boxing;	}	public B4list(String tagName, boolean boxing) {		super(tagName);		this.boxing = boxing;	}	public T active() {		if (this.boxing) {			super.boxes();		}		((Tag<?>) super.last()).cssClass(B4ctrl.active);		return super.bean();	}	public T active(int index) {		if (this.boxing) {			super.boxes();		}		((Tag<?>) super.get(index)).cssClass(B4ctrl.active);		return super.bean();	}	public T disabled() {		if (this.boxing) {			super.boxes();		}		((Tag<?>) super.last()).cssClass(B4ctrl.disabled);		return super.bean();	}	public T disabled(int index) {		if (this.boxing) {			super.boxes();		}		((Tag<?>) super.get(index)).cssClass(B4ctrl.disabled);		return super.bean();	}	}